"""Phase 2 tests: synthetic scenarios generated by EPANET (via WNTR).

The fixture below runs the REAL pipeline in quick mode (50 scenarios) into a temporary folder, so the tests
never depend on stale files. Run `python scripts/build_network.py` first so the base .inp exists.
"""
import copy
import json
import sys
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[1]))

import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
import pytest  # noqa: E402

from src.labels import (FLAG_COLUMNS, RISK_LABELS, compute_flags, label_settings, label_timeseries,  # noqa: E402
                        primary_labels, scenario_label)
from src.scenario_generator import (FAMILIES, FAMILY_GROUPS, METADATA_COLUMNS, allocate_counts,  # noqa: E402
                                    apply_sensor_noise, generate_dataset, sample_spec)
from src.simulation import RAW_COLUMNS, run_scenario, validate_timeseries  # noqa: E402
from src.utils import load_config, resolve_path  # noqa: E402

REQUIRED_RAW_COLUMNS = [
    "scenario_id", "timestamp", "scenario_type", "J1_pressure", "J2_pressure", "J3_pressure", "J4_pressure",
    "P1_flow", "P2_flow", "P3_flow", "P4_flow", "J2_demand", "J3_demand", "J4_demand", "tank_level",
    "reservoir_head", "pump_speed", "pump_status", "valve_setting", "valve_status", "leak_flag", "leak_severity",
]
REQUIRED_METADATA_COLUMNS = [
    "scenario_id", "scenario_type", "random_seed", "reservoir_head", "tank_initial_level", "pump_speed",
    "pump_schedule", "valve_setting", "leak_node", "leak_start_time", "leak_end_time", "leak_severity",
    "blockage_pipe", "blockage_factor", "demand_profile_id", "notes",
]
REQUIRED_SUMMARY_COLUMNS = [
    "scenario_id", "scenario_type", "status", "warnings", "error", "pressure_spread_max", "min_J4_pressure",
    "n_pressure_violations", "J1_min_pressure", "J1_max_pressure", "J2_min_pressure", "J2_max_pressure",
    "J3_min_pressure", "J3_max_pressure", "J4_min_pressure", "J4_max_pressure",
]
PATH_KEYS = {"scenario_metadata": "scenario_metadata.csv", "raw_timeseries": "raw_timeseries.csv",
             "labels": "labels.csv", "demand_profiles": "demand_profiles.csv",
             "scenario_specs": "scenario_specs.jsonl", "sensor_timeseries": "sensor_timeseries.csv",
             "summary": "summary.csv", "network_config_json": "network_config.json"}


def _paths(folder: Path) -> dict:
    out = {k: str(folder / v) for k, v in PATH_KEYS.items()}
    out["log_dir"] = str(folder / "logs")
    return out


@pytest.fixture(scope="module")
def cfg():
    return load_config()


@pytest.fixture(scope="module")
def base_inp(cfg):
    p = resolve_path(cfg["paths"]["base_inp"])
    if not p.exists():
        pytest.fail(f"{p} not found. Run: python scripts/build_network.py")
    return p


@pytest.fixture(scope="module")
def quick(cfg, base_inp, tmp_path_factory):
    """Run the real quick-mode pipeline once and read every output back from disk."""
    folder = tmp_path_factory.mktemp("phase2_quick")
    n = cfg["scenarios"]["quick_n"]
    result = generate_dataset(cfg, n, paths=_paths(folder), quiet=True)
    P = result["paths"]
    meta_disk = pd.read_csv(P["scenario_metadata"])
    for col in ("leak_node", "blockage_pipe"):        # blank text cells are read back as NaN
        meta_disk[col] = meta_disk[col].fillna("")
    result["disk"] = {
        "metadata": meta_disk,
        "raw": pd.read_csv(P["raw_timeseries"]),
        "labels": pd.read_csv(P["labels"]),
        "summary": pd.read_csv(P["summary"]),
        "profiles": pd.read_csv(P["demand_profiles"]),
        "specs": [json.loads(line) for line in open(P["scenario_specs"], encoding="utf-8")],
        "network_config": json.loads(open(P["network_config_json"], encoding="utf-8").read()),
    }
    return result


