# ------------------------------------------------------------------------------ 2. 96 time steps
def test_each_scenario_has_96_time_steps(quick):
    raw = quick["disk"]["raw"]
    sizes = raw.groupby("scenario_id").size()
    assert (sizes == 96).all(), sizes[sizes != 96]
    ts = pd.to_datetime(raw["timestamp"])
    for _, block in raw.assign(ts=ts).groupby("scenario_id"):
        assert block["ts"].iloc[0].strftime("%H:%M") == "00:00"
        assert block["ts"].iloc[-1].strftime("%H:%M") == "23:45"
        assert (block["ts"].diff().dropna() == pd.Timedelta(minutes=15)).all()


