# ------------------------------------------------------------------------------ 5. real EPANET output
def test_data_is_real_epanet_output(quick, cfg, base_inp):
    d = quick["disk"]
    raw, specs = d["raw"], {s["scenario_id"]: s for s in d["specs"]}

    # (a) Re-running a saved spec through EPANET reproduces the saved rows exactly (deterministic solver output).
    by_type = d["metadata"].drop_duplicates("scenario_type").set_index("scenario_type")["scenario_id"]
    assert set(by_type.index) == set(FAMILIES), "quick mode should contain every scenario family"
    for family, sid in by_type.items():
        again = run_scenario(specs[sid], cfg, base_inp)
        assert again["data"] is not None, again["error"]
        saved = raw[raw["scenario_id"] == sid].reset_index(drop=True)
        for col in [c for c in REQUIRED_RAW_COLUMNS if c not in ("scenario_id", "timestamp", "scenario_type", "tank_level")]:
            assert np.allclose(again["data"][col].to_numpy(dtype=float), saved[col].to_numpy(dtype=float),
                               atol=1e-3), f"{family}/{sid}/{col} differs from a fresh EPANET run"

    # (b) Physics that random numbers would not satisfy: flow balance at every junction, every time step.
    meta = d["metadata"].set_index("scenario_id")
    leak_node = raw["scenario_id"].map(meta["leak_node"]).fillna("")
    leak = raw["leak_severity"]
    tol = np.maximum(0.03, 0.004 * raw["P1_flow"].abs())
    for pipe, node in (("P2", "J2"), ("P3", "J3"), ("P4", "J4")):
        expected = raw[f"{node}_demand"] + leak.where(leak_node == node, 0.0)
        assert (raw[f"{pipe}_flow"] - expected).abs().le(tol).all(), f"flow balance broken at {node}"
    expected_p1 = raw[["P2_flow", "P3_flow", "P4_flow"]].sum(axis=1) + leak.where(leak_node == "J1", 0.0)
    assert (raw["P1_flow"] - expected_p1).abs().le(tol).all(), "flow balance broken at J1"

    # (c) The saved demand profile is what EPANET delivered (when the node has enough pressure for full demand).
    prof = d["profiles"].set_index(["demand_profile_id", "step"])
    base_demand = {j["id"]: j["base_demand_lps"] for j in cfg["network"]["junctions"]}
    checked = 0
    for sid, block in raw.groupby("scenario_id"):
        pid = meta.loc[sid, "demand_profile_id"]
        for node in ("J2", "J3", "J4"):
            full = block[f"{node}_pressure"].to_numpy() >= cfg["simulation"]["pdd_required_pressure_m"]
            wanted = base_demand[node] * prof.loc[pid][f"{node}_multiplier"].to_numpy()
            got = block[f"{node}_demand"].to_numpy()
            assert np.allclose(got[full], wanted[full], atol=2e-3), f"{sid}/{node} delivered demand != profile"
            checked += int(full.sum())
    assert checked > 0

    # (d) Provenance file names EPANET and matches the network file that was simulated.
    import hashlib
    nc = d["network_config"]
    assert "EPANET" in nc["simulator"]["engine"]
    assert nc["base_inp"]["sha256"] == hashlib.sha256(base_inp.read_bytes()).hexdigest()
    assert nc["network"]["has_tank"] is False


# ------------------------------------------------------------------------------ 6. no invalid rows silently accepted
def test_accepted_data_has_no_invalid_values(quick, cfg):
    d = quick["disk"]
    raw, v = d["raw"], cfg["validation"]
    filled = raw.drop(columns=["scenario_id", "timestamp", "scenario_type", "tank_level"])
    assert not filled.isna().any().any()
    assert np.isfinite(filled.to_numpy(dtype=float)).all()
    assert raw["tank_level"].isna().all(), "tank_level must stay empty: the network has no tank"
    assert d["metadata"]["tank_initial_level"].isna().all()
    for c in [c for c in raw.columns if c.endswith("_pressure")]:
        assert raw[c].between(v["min_valid_pressure_m"], v["max_valid_pressure_m"]).all()
    assert set(d["summary"]["status"]) <= {"ok", "ok_with_warnings", "rejected", "failed"}
    accepted = set(d["summary"].query("status in ['ok', 'ok_with_warnings']")["scenario_id"])
    assert set(raw["scenario_id"]) == accepted


def test_warnings_are_recorded_not_hidden(quick):
    s = quick["disk"]["summary"]
    flagged = s[s["status"] == "ok_with_warnings"]
    assert flagged["warnings"].notna().all() and (flagged["warnings"] != "").all()
    assert s[s["status"] == "ok"]["warnings"].fillna("").eq("").all()


def test_bad_scenarios_fail_loudly(cfg, base_inp, quick):
    spec = copy.deepcopy(quick["disk"]["specs"][0])
    # pressures outside the configured valid window -> rejected, no data returned
    strict = copy.deepcopy(cfg); strict["validation"]["min_valid_pressure_m"] = 500.0
    r = run_scenario(spec, strict, base_inp)
    assert r["status"] == "rejected" and r["data"] is None and "outside valid range" in r["error"]
    # an unknown pipe makes WNTR/EPANET raise -> failed, no data
    broken = copy.deepcopy(spec); broken["blockage"] = {"pipe": "NO_SUCH_PIPE", "factor": 0.5}
    r = run_scenario(broken, cfg, base_inp)
    assert r["status"] == "failed" and r["data"] is None and r["error"]
    # validation catches NaN, a short series and a gap in time
    good = quick["raw"][quick["raw"]["scenario_id"] == spec["scenario_id"]].copy()
    good["timestamp"] = pd.to_datetime(good["timestamp"])
    assert validate_timeseries(good, cfg) == []
    nan = good.copy(); nan.loc[nan.index[5], "J2_pressure"] = np.nan
    assert validate_timeseries(nan, cfg)
    assert validate_timeseries(good.iloc[:-1], cfg)
    gap = good.drop(good.index[10])
    assert validate_timeseries(gap, cfg)


def test_pipeline_does_not_accept_rejected_scenarios(cfg, base_inp, tmp_path):
    """If every attempt is rejected, nothing is written to the data files and the run reports 'incomplete'."""
    bad = copy.deepcopy(cfg)
    bad["scenarios"]["family_fractions"] = {"normal": 1.0}
    bad["scenarios"]["max_attempts_per_slot"] = 2
    bad["validation"]["min_valid_pressure_m"] = 500.0      # nothing can pass -> every attempt is rejected
    out = generate_dataset(bad, 2, paths=_paths(tmp_path), quiet=True)
    assert out["complete"] is False and out["n_accepted"] == 0
    assert len(out["raw"]) == 0 and len(out["metadata"]) == 0
    assert (out["summary"]["status"] == "rejected").all() and len(out["summary"]) == 4
    assert pd.read_csv(out["paths"]["raw_timeseries"]).empty


# ------------------------------------------------------------------------------ 7. metadata <-> time series
def test_metadata_matches_timeseries(quick):
    d = quick["disk"]
    meta, raw, labels = d["metadata"], d["raw"], d["labels"]
    assert set(meta["scenario_id"]) == set(raw["scenario_id"]) == set(labels["scenario_id"])
    assert {s["scenario_id"] for s in d["specs"]} == set(meta["scenario_id"])
    m = meta.set_index("scenario_id")
    for sid, block in raw.groupby("scenario_id"):
        row = m.loc[sid]
        assert (block["scenario_type"] == row["scenario_type"]).all()
        assert abs(block["valve_setting"].mean() - row["valve_setting"]) < 1e-2
        assert block["reservoir_head"].max() <= row["reservoir_head"] * 1.05
        assert block["pump_speed"].max() <= row["pump_speed"] + 1e-3
        if row["leak_node"]:
            on = block["leak_flag"] == 1
            hours = pd.to_datetime(block["timestamp"]).dt.hour + pd.to_datetime(block["timestamp"]).dt.minute / 60
            assert on.sum() == round((row["leak_end_time"] - row["leak_start_time"]) * 4)
            assert hours[on].min() == row["leak_start_time"]
            assert (block.loc[on, "leak_severity"] > 0).any()
            assert (block.loc[~on, "leak_severity"] == 0).all()
        else:
            assert (block["leak_flag"] == 0).all() and (block["leak_severity"] == 0).all()
    typed = meta.groupby("scenario_type")
    assert typed["leak_node"].apply(lambda s: s.ne("").all())[["small_leak", "burst_leak"]].all()
    assert meta.loc[meta["scenario_type"] == "partial_blockage", "blockage_pipe"].ne("").all()
    assert meta.loc[~meta["scenario_type"].eq("partial_blockage"), "blockage_pipe"].fillna("").eq("").all()


def test_pump_speed_in_data_is_the_speed_in_the_spec(quick):
    """EPANET treats a speed pattern as absolute speed: the saved speed must equal the spec, step by step."""
    d = quick["disk"]
    specs = {s["scenario_id"]: s for s in d["specs"]}
    checked = 0
    for sid, block in d["raw"].groupby("scenario_id"):
        spec = specs[sid]
        expected = spec["pump_pattern"] if spec["pump_pattern"] is not None else [spec["pump_speed"]] * 96
        assert np.allclose(block["pump_speed"].to_numpy(), expected, atol=1e-3), f"{sid}: pump speed != spec"
        checked += spec["pump_pattern"] is not None
    assert checked >= 1, "quick mode should contain at least one pump_degradation scenario"


