# ------------------------------------------------------------------------------ 8. labels follow thresholds
def _independent_flags(raw: pd.DataFrame, cfg: dict) -> pd.DataFrame:
    th, lab = cfg["thresholds"], cfg["labels"]
    p = raw[["J2_pressure", "J3_pressure", "J4_pressure"]]
    spread = p.max(axis=1) - p.min(axis=1)
    on = (raw["leak_flag"] == 1) & (raw["leak_severity"] >= lab["leak_min_lps"])
    return pd.DataFrame({
        "low_pressure_flag": ((p < th["p_min_m"]).any(axis=1) | (raw["J4_pressure"] < th["critical_p_min_m"])).astype(int),
        "high_pressure_flag": (p > th["p_max_m"]).any(axis=1).astype(int),
        "imbalance_flag": (spread > th["max_pressure_spread_m"]).astype(int),
        "burst_event_flag": (on & (raw["leak_severity"] >= lab["burst_min_lps"])).astype(int),
        "leak_event_flag": (on & (raw["leak_severity"] < lab["burst_min_lps"])).astype(int),
    })


def test_labels_follow_configured_thresholds(quick, cfg):
    raw, labels = quick["disk"]["raw"], quick["disk"]["labels"]
    assert (raw[["scenario_id", "timestamp"]].values == labels[["scenario_id", "timestamp"]].values).all()
    expected = _independent_flags(raw, cfg)
    for col in expected.columns:
        assert (labels[col].to_numpy() == expected[col].to_numpy()).all(), col
    assert set(labels["risk_label"]) <= set(RISK_LABELS)
    assert (labels["risk_label"].eq("normal") == (labels[list(FLAG_COLUMNS)].sum(axis=1) == 0)).all()


def test_labels_change_when_thresholds_change(quick, cfg):
    raw = quick["raw"]
    strict = copy.deepcopy(cfg); strict["thresholds"]["p_min_m"] = 45.0
    lax = copy.deepcopy(cfg); lax["thresholds"]["p_max_m"] = 200.0
    base = label_timeseries(raw, cfg)
    assert label_timeseries(raw, strict)["low_pressure_flag"].sum() > base["low_pressure_flag"].sum()
    assert label_timeseries(raw, lax)["high_pressure_flag"].sum() == 0 < base["high_pressure_flag"].sum()


def test_label_boundaries_and_priority(cfg):
    s = label_settings(cfg)
    p_min, p_max, spread, crit = s["p_min_m"], s["p_max_m"], s["max_spread_m"], s["critical_p_min_m"]

    def frame(j2, j3, j4, leak_flag=0, leak=0.0):
        return pd.DataFrame({"scenario_id": ["T"], "timestamp": ["t"], "J1_pressure": [50.0], "J2_pressure": [j2],
                             "J3_pressure": [j3], "J4_pressure": [j4], "leak_flag": [leak_flag], "leak_severity": [leak]})

    def flags(**kw):
        return compute_flags(frame(**kw), s).iloc[0]

    ok = dict(j2=45.0, j3=45.0, j4=45.0)
    assert flags(**ok)[list(FLAG_COLUMNS)].sum() == 0
    assert flags(**{**ok, "j2": p_min})["low_pressure_flag"] == 0            # exactly p_min is allowed
    assert flags(**{**ok, "j2": p_min - 0.01})["low_pressure_flag"] == 1
    assert flags(**{**ok, "j4": crit})["low_pressure_flag"] == 0             # exactly the critical minimum is allowed
    assert flags(**{**ok, "j4": crit - 0.01})["low_pressure_flag"] == 1      # J4 needs more than other junctions
    assert flags(**{**ok, "j3": p_max})["high_pressure_flag"] == 0
    assert flags(**{**ok, "j3": p_max + 0.01})["high_pressure_flag"] == 1
    assert flags(j2=30.0, j3=30.0 + spread, j4=30.0 + spread)["imbalance_flag"] == 0   # exactly the spread is allowed
    assert flags(j2=30.0, j3=30.0 + spread + 0.01, j4=35.0)["imbalance_flag"] == 1
    small, big = s["leak_min_lps"] * 2, s["burst_min_lps"] + 0.1
    assert flags(**ok, leak_flag=1, leak=small)["leak_event_flag"] == 1
    assert flags(**ok, leak_flag=1, leak=big)["burst_event_flag"] == 1
    assert flags(**ok, leak_flag=0, leak=big)[["leak_event_flag", "burst_event_flag"]].sum() == 0

    # priority: burst > leak > low > high > imbalance > normal
    every = pd.DataFrame([{"low_pressure_flag": 1, "high_pressure_flag": 1, "imbalance_flag": 1,
                           "leak_event_flag": 1, "burst_event_flag": 1}])
    order = [("burst_event_flag", "burst_like_event"), ("leak_event_flag", "leak_like_event"),
             ("low_pressure_flag", "low_pressure_risk"), ("high_pressure_flag", "high_pressure_risk"),
             ("imbalance_flag", "pressure_imbalance")]
    for flag, label in order:
        assert primary_labels(every, s["priority"]).iloc[0] == label
        every[flag] = 0
    assert primary_labels(every, s["priority"]).iloc[0] == "normal"
    both = pd.DataFrame({"low_pressure_flag": [1, 0], "high_pressure_flag": [0, 1], "imbalance_flag": [1, 1],
                         "leak_event_flag": [0, 0], "burst_event_flag": [0, 0]})
    assert scenario_label(both, s["priority"]) == "low_pressure_risk"


def test_physics_gives_expected_labels(quick):
    """Scenario families should do what their names say (a sanity check of the whole chain)."""
    s = quick["disk"]["summary"]
    ok = s[s["status"].isin(["ok", "ok_with_warnings"])]
    lab = ok.groupby("scenario_type")["scenario_risk_label"].agg(lambda x: x.value_counts().to_dict())
    assert lab["normal"] == {"normal": int((ok["scenario_type"] == "normal").sum())}
    assert set(lab["high_source_pressure"]) == {"high_pressure_risk"}
    assert set(lab["high_demand_stress"]) == {"low_pressure_risk"}
    assert set(lab["small_leak"]) == {"leak_like_event"}
    assert set(lab["burst_leak"]) == {"burst_like_event"}
    assert set(lab["reduced_supply"]) == {"low_pressure_risk"}


# ------------------------------------------------------------------------------ 9. no mixing between scenarios
def test_scenario_data_is_not_mixed(quick):
    raw = quick["disk"]["raw"]
    order = raw["scenario_id"].ne(raw["scenario_id"].shift()).cumsum()
    assert order.nunique() == raw["scenario_id"].nunique(), "rows of one scenario are not contiguous"
    assert raw.groupby("scenario_id")["scenario_type"].nunique().eq(1).all()
    labels = quick["disk"]["labels"]
    assert (labels.groupby("scenario_id")["timestamp"].nunique() == 96).all()
    assert labels["scenario_id"].tolist() == raw["scenario_id"].tolist()
    # every scenario is a distinct simulation: no two scenarios share an identical pressure curve
    curves = raw.groupby("scenario_id")["J3_pressure"].apply(lambda s: tuple(s.round(3)))
    assert curves.is_unique


def test_scenarios_are_reproducible(cfg):
    a = sample_spec(cfg, "burst_leak", 7, 1, 42)
    assert a == sample_spec(cfg, "burst_leak", 7, 1, 42)
    assert a != sample_spec(cfg, "burst_leak", 7, 1, 43)
    assert a != sample_spec(cfg, "burst_leak", 7, 2, 42)
    assert a["leak"]["node"] in cfg["scenarios"]["ranges"]["burst_leak"]["leak_nodes"]


def test_allocation_rules(cfg):
    for n in (9, 50, 120, 300):
        counts = allocate_counts(n, cfg["scenarios"]["family_fractions"])
        assert sum(counts.values()) == n and min(counts.values()) >= 1
    with pytest.raises(ValueError):
        allocate_counts(50, {"normal": 0.5, "burst_leak": 0.4})


# ------------------------------------------------------------------------------ optional sensor noise
def test_sensor_noise_is_added_to_a_copy_only(quick, cfg):
    raw = quick["raw"]
    before = raw.copy(deep=True)
    noisy = apply_sensor_noise(raw, cfg, seed=1)
    pd.testing.assert_frame_equal(raw, before)                            # raw untouched
    assert not noisy["J3_pressure"].equals(raw["J3_pressure"])
    assert abs((noisy["J3_pressure"] - raw["J3_pressure"]).std() - cfg["sensor_noise"]["pressure_sd_m"]) < 0.05
    for col in ("scenario_id", "timestamp", "leak_flag", "pump_status", "valve_setting"):
        assert noisy[col].equals(raw[col])
    assert cfg["sensor_noise"]["enabled"] is False                         # off by default


# ------------------------------------------------------------------------------ repo outputs (if generated)
def test_repo_outputs_if_present(cfg):
    meta_path = resolve_path(cfg["paths"]["scenario_metadata"])
    raw_path = resolve_path(cfg["paths"]["raw_timeseries"])
    if not (meta_path.exists() and raw_path.exists()):
        pytest.skip("run scripts/generate_synthetic_data.py to create data/synthetic/ first")
    meta, raw = pd.read_csv(meta_path), pd.read_csv(raw_path)
    assert list(raw.columns) == REQUIRED_RAW_COLUMNS
    assert list(meta.columns) == REQUIRED_METADATA_COLUMNS
    assert set(meta["scenario_id"]) == set(raw["scenario_id"])
    assert (raw.groupby("scenario_id").size() == 96).all()
